import type { Fixture } from "@/types/hockey";
import { HULL_HAWKS_TEAM, isHawksHome, opponentForHawks } from "@/lib/hockey";

const formatter = new Intl.DateTimeFormat("en-GB", {
  weekday: "short",
  day: "2-digit",
  month: "short",
});

export function FixtureList({ fixtures }: { fixtures: Fixture[] }) {
  return (
    <div className="divide-y divide-white/10 border-y border-white/10">
      {fixtures.map((fixture) => (
        <div
          key={fixture.id}
          className="grid gap-3 py-5 md:grid-cols-[160px_1fr_auto] md:items-center"
        >
          <div>
            <p className="font-black uppercase tracking-wide">
              {formatter.format(new Date(`${fixture.date}T12:00:00`))}
            </p>
            <p className="mt-1 text-sm text-white/40">
              {fixture.time ?? "TBC"}
            </p>
          </div>
          <div>
            <p className="text-lg font-black uppercase">
              {HULL_HAWKS_TEAM}
              <span className="mx-3 font-normal text-white/25">
                {isHawksHome(fixture) ? "vs" : "at"}
              </span>
              {opponentForHawks(fixture)}
            </p>
            {fixture.venue && (
              <p className="mt-1 text-sm text-white/40">{fixture.venue}</p>
            )}
          </div>
          <span className="w-fit rounded-sm border border-white/15 px-3 py-2 text-[10px] font-black uppercase tracking-[0.14em] text-white/55">
            {isHawksHome(fixture) ? "Home" : "Away"}
          </span>
        </div>
      ))}
    </div>
  );
}
