import { BrandMark } from "@/components/BrandMark";

export function Header() {
  return (
    <header className="absolute inset-x-0 top-0 z-50 border-b border-white/5 bg-black/30 backdrop-blur-sm">
      <div className="mx-auto flex max-w-[1450px] items-center justify-between px-5 py-4 md:px-8 lg:px-12">
        <a href="#" aria-label="Hull Hawks home" className="shrink-0">
          <BrandMark compact />
        </a>

        <nav className="hidden items-center gap-8 lg:flex">
          {[
            ["Home", "#"],
            ["Fixtures", "#fixtures"],
            ["Table", "#table"],
            ["Team", "#team"],
            ["About", "#about"],
            ["Sponsors", "#sponsors"],
            ["Contact", "#contact"],
          ].map(([label, href], index) => (
            <a
              key={label}
              href={href}
              className={`relative py-2 text-xs font-bold uppercase tracking-[0.14em] text-white/80 transition hover:text-white ${
                index === 0
                  ? "after:absolute after:inset-x-0 after:-bottom-2 after:h-[2px] after:bg-[var(--red)]"
                  : ""
              }`}
            >
              {label}
            </a>
          ))}
        </nav>

        <div className="flex items-center gap-4">
          <a
            href="https://www.instagram.com/hullhawks/"
            target="_blank"
            rel="noreferrer"
            aria-label="Hull Hawks Instagram"
            className="grid h-10 w-10 place-items-center rounded-full border border-white/20 text-lg transition hover:border-[var(--red)] hover:text-[var(--red)]"
          >
            ◎
          </a>
          <a
            href="#sponsors"
            className="hidden rounded-md bg-[var(--red)] px-5 py-3 text-xs font-black uppercase tracking-[0.08em] transition hover:bg-[var(--red-dark)] sm:block"
          >
            Support us
          </a>
        </div>
      </div>
    </header>
  );
}
