import type { LeagueRow } from "@/types/hockey";
import { HULL_HAWKS_TEAM } from "@/lib/hockey";

export function LeagueTable({
  rows,
  compact = false,
}: {
  rows: LeagueRow[];
  compact?: boolean;
}) {
  const visibleRows = compact ? rows.slice(0, 5) : rows;

  return (
    <div
      className={
        compact ? "" : "overflow-hidden rounded-xl border border-white/10"
      }
    >
      <div className="overflow-x-auto">
        <table className="w-full min-w-[540px] border-collapse text-left">
          <thead className="text-[10px] uppercase tracking-[0.14em] text-white/45">
            <tr className="border-b border-white/10">
              <th className="px-3 py-3">#</th>
              <th className="px-3 py-3">Team</th>
              <th className="px-3 py-3 text-center">P</th>
              {!compact && <th className="px-3 py-3 text-center">W</th>}
              {!compact && <th className="px-3 py-3 text-center">D</th>}
              {!compact && <th className="px-3 py-3 text-center">L</th>}
              {!compact && <th className="px-3 py-3 text-center">GD</th>}
              <th className="px-3 py-3 text-right">Pts</th>
            </tr>
          </thead>
          <tbody>
            {visibleRows.map((row) => {
              const hawks = row.team === HULL_HAWKS_TEAM;
              return (
                <tr
                  key={row.team}
                  className={
                    hawks
                      ? "bg-[linear-gradient(90deg,var(--red-dark),var(--red))] text-white"
                      : "border-b border-white/[0.07]"
                  }
                >
                  <td className="px-3 py-3 font-bold">{row.position}</td>
                  <td className="px-3 py-3 font-bold">{row.team}</td>
                  <td className="px-3 py-3 text-center">{row.played}</td>
                  {!compact && (
                    <td className="px-3 py-3 text-center">{row.won}</td>
                  )}
                  {!compact && (
                    <td className="px-3 py-3 text-center">{row.drawn}</td>
                  )}
                  {!compact && (
                    <td className="px-3 py-3 text-center">{row.lost}</td>
                  )}
                  {!compact && (
                    <td className="px-3 py-3 text-center">
                      {row.goalDifference > 0 ? "+" : ""}
                      {row.goalDifference}
                    </td>
                  )}
                  <td className="px-3 py-3 text-right font-black">
                    {row.points}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}
