import {
  HULL_HAWKS_TEAM,
  isHawksHome,
  opponentForHawks,
  resultForHawks,
} from "@/lib/hockey";
import type { Fixture } from "@/types/hockey";
import { BrandMark } from "@/components/BrandMark";

const dateFormatter = new Intl.DateTimeFormat("en-GB", {
  weekday: "short",
  day: "numeric",
  month: "short",
  year: "numeric",
});

export function MatchCard({
  fixture,
  kind,
}: {
  fixture?: Fixture;
  kind: "next" | "result";
}) {
  if (!fixture) {
    return (
      <article className="sports-panel rounded-xl p-6">
        <p className="section-kicker">
          {kind === "next" ? "Next match" : "Latest result"}
        </p>
        <p className="mt-10 text-white/40">No match available.</p>
      </article>
    );
  }

  const result = resultForHawks(fixture);
  const hawksHome = isHawksHome(fixture);
  const hawksScore = hawksHome ? fixture.homeScore : fixture.awayScore;
  const opponentScore = hawksHome ? fixture.awayScore : fixture.homeScore;

  return (
    <article className="sports-panel rounded-xl p-6">
      <div className="flex items-start justify-between gap-5">
        <p className="section-kicker">
          {kind === "next" ? "Next match" : "Latest result"}
        </p>
        <p className="max-w-[150px] text-right text-[10px] font-bold uppercase tracking-[0.12em] text-white/45">
          YNE Peak &amp; Wold Women&apos;s Division 1
        </p>
      </div>

      <div className="mt-8 grid grid-cols-[1fr_auto_1fr] items-center gap-4">
        <div className="text-center">
          <div className="mx-auto flex h-20 items-center justify-center">
            <BrandMark compact />
          </div>
          <p className="mt-4 font-black uppercase tracking-wide">
            {HULL_HAWKS_TEAM}
          </p>
          <p className="mini-label mt-2 text-white/40">
            {hawksHome ? "Home" : "Away"}
          </p>
        </div>

        {kind === "next" ? (
          <div className="flex items-center gap-3">
            <div className="h-16 w-[2px] bg-[var(--red)]" />
            <span className="text-sm font-black uppercase tracking-[0.18em] text-white/80">
              VS
            </span>
            <div className="h-16 w-[2px] bg-[var(--red)]" />
          </div>
        ) : (
          <div className="rounded-md bg-[var(--red)] px-5 py-4 text-3xl font-black">
            {hawksScore ?? "-"} <span className="text-white/60">-</span>{" "}
            {opponentScore ?? "-"}
          </div>
        )}

        <div className="text-center">
          <div className="mx-auto grid h-20 w-20 place-items-center rounded-full border border-white/15 bg-white/[0.03] text-2xl font-black text-white/30">
            {opponentForHawks(fixture)
              .split(" ")
              .map((part) => part[0])
              .join("")
              .slice(0, 2)}
          </div>
          <p className="mt-4 font-black uppercase tracking-wide">
            {opponentForHawks(fixture)}
          </p>
          <p className="mini-label mt-2 text-white/40">
            {hawksHome ? "Away" : "Home"}
          </p>
        </div>
      </div>

      <div className="mt-7 border-t border-white/10 pt-5">
        {kind === "result" ? (
          <>
            <p className="text-center text-sm text-white/80">
              {dateFormatter.format(new Date(`${fixture.date}T12:00:00`))}
              <span className="mx-3 text-white/25">|</span>
              {hawksHome ? "HOME" : "AWAY"}
            </p>
            {result && (
              <div className="mx-auto mt-4 max-w-[200px] bg-[var(--red-dark)]/55 py-2 text-center text-xs font-black uppercase tracking-[0.12em]">
                {result === "W" ? "Win" : result === "D" ? "Draw" : "Loss"}
              </div>
            )}
          </>
        ) : (
          <div className="grid gap-3 text-sm text-white/80 sm:grid-cols-3">
            <span>
              ▣ &nbsp;
              {dateFormatter.format(new Date(`${fixture.date}T12:00:00`))}
            </span>
            <span>◷ &nbsp;{fixture.time ?? "TBC"}</span>
            <span>⌖ &nbsp;{fixture.venue ?? "TBC"}</span>
          </div>
        )}
      </div>
    </article>
  );
}
